// ── A: the transfer-direction × lifecycle quadrant's H2D-immutable member —
// an operand immutable across evaluations lives in a device buffer of the
// CONSUMER's buffer type, classified WEIGHTS usage, written once at init. ──
fn slice_b320_remainder() -> Vec<KernelRule> {
    vec![
        KernelRule {
            rule_id: "immutable-operand-device-resident-per-buffer-type".to_string(),
            gpu_concept: "MECHANISM (the H2D-immutable quadrant of the transfer-direction x lifecycle matrix; category A — MemoryAccess): an operand IMMUTABLE across evaluations that a kernel consumes every call must live in a DEVICE buffer of the CONSUMER's own buffer type, classified into the weights usage class, and written ONCE at init — never staged in host memory as a graph input the backend re-uploads every evaluation. Source: ggml-org/llama.cpp @ fb59972 #31073 'kv-cache : keep rotation constants on the GPU' (MIT): the KV-cache Hadamard rotation constants were host tensors fed as graph inputs, so every ubatch paid the H2D copy — the commit's own parent carried the TODO it implements, verbatim [in-diff, removed] src/llama-kv-cache.cpp:353 'TODO: in the future, we can make copies in the backend buffers to avoid host -> device transfers', over the removed per-eval host path [in-diff, removed] :1471/1487 'GGML_ASSERT(ggml_backend_buffer_is_host(dst->buffer));' + 'memcpy(dst->data, attn_rot_hadamard.at(n_rot).data(), ggml_nbytes(dst));'. The fix places the constants init-once, keyed to the consumer: [in-diff] :392 'const auto buft = ggml_backend_buffer_get_type(cache->buffer);' (a ctx map per buffer type — the multi-device split gets one resident buffer per consumer type), [in-diff] :409-410 'auto * buf = attn_rot_bufs.emplace(std::move(ctx), buft, \"rotation matrices\");' + 'ggml_backend_buffer_set_usage(buf, GGML_BACKEND_BUFFER_USAGE_WEIGHTS);' (the constants join the WEIGHTS usage class — alloc accounting and lifetime follow the weights, not the activations), one init write per buffer [in-diff] 'ggml_backend_tensor_set(t, attn_rot_hadamard.at(t->ne[0]).data(), 0, ggml_nbytes(t));', per-layer granularity [in-diff] :403 'ggml_format_name(rot, \"cache_%s%s_rot_l%d\", name_tag, is_k ? \"k\" : \"v\", layer.il);'. THE QUADRATIC COMPLETION: host-cache-immutable-device-weights (B26, gpu_02) owns D2H-immutable (device constants cloned to CPU once for cheap host gathers); kv-window-device-resident-ring-append (B182-era, gpu_04) owns H2D-mutable ('an operand mutated incrementally crosses the bus incrementally'); THIS owns H2D-immutable — the constant's place is beside its consumer on the device, never a per-eval upload. Distinct from table-reached-buffers-declare-residency (gpu_134 — DECLARES residency for table-indirect buffers; THIS chooses the PLACEMENT and usage class at init), from tied-hadamard-output-fold-at-load (gpu_66 — bakes the transform into the weight format at pack time; the rotation matrices here stay RUNTIME transforms resident beside the cache), and from the cachedNarrowZeros ladder (gpu_51's Batch-213 rider — 'fold-into-read > once-resident-shared > per-call': this moves its operand from the per-call rung to once-resident-shared). NotBenchable here (placement/traffic axis, the quadrant siblings' class; the upload-count and idempotent-init behavior is CPU-testable and IS the fixture). Provenance: commit message 'Assisted-by: Codex' (LLM-co-authored); the PR's mid-history added then DROPPED its own rotation-buffer tests ('tests: drop the rotation buffer tests' sub-commit) — the landed tree carries no device-side test for the residency. Batch 320 / Plan 320.".to_string(),
            ref_shape: "// naive: rotation constants live host-side and ride EVERY ubatch as\n// graph inputs — the backend copies them H2D per evaluation\n// (llama-kv-cache.cpp:1471/1487 pre-fb59972):\n//   GGML_ASSERT(ggml_backend_buffer_is_host(dst->buffer));\n//   memcpy(dst->data, attn_rot_hadamard.at(n_rot).data(), ggml_nbytes(dst));\n// every ubatch: host -> device copy of the SAME immutable bytes; the\n// parent TODO named it: 'we can make copies in the backend buffers to\n// avoid host -> device transfers'\nfn graph_build_per_ubatch(host_rot: &[f32], inputs: &mut Vec<Input>) {\n    inputs.push(Input::host_tensor(host_rot)); // re-uploaded every eval\n}".to_string(),
            opt_pattern: "// optimized: init once per CONSUMER buffer type, weights usage class,\n// one write; the graph reads the resident tensor directly\nfn init_rotation(cache: &KvCache, host_rot: &[f32]) -> Tensor {\n    // placement keyed to the consumer's own buffer type (multi-device safe):\n    let buft = ggml_backend_buffer_get_type(cache.buffer);\n    let buf = bufs_for(buft).emplace(\"rotation matrices\");\n    ggml_backend_buffer_set_usage(buf, GGML_BACKEND_BUFFER_USAGE_WEIGHTS);\n    let rot = ggml_new_tensor_2d(ctx, GGML_TYPE_F32, n_rot, n_rot);\n    ggml_format_name(rot, \"cache_%s%s_rot_l%d\", tag, k_or_v, layer);\n    ggml_backend_tensor_set(rot, host_rot, 0, ggml_nbytes(rot)); // the ONE write\n    rot\n} // every later ubatch: zero uploads — the tensor is a device constant\n  // beside its consumer; idempotent re-init for the same buffer type".to_string(),
        },
        // ── N: a word of byte-wide minifloat codes converts natively out of its
        // one register — the byte-isolation spelling is the anti-shape. ──
        KernelRule {
            rule_id: "word-native-byte-pair-minifloat-conversion".to_string(),
            gpu_concept: "MECHANISM (conversion-granularity-of-a-word; category N — DtypeAlignment, the cast-path lowering axis): a WORD of byte-wide minifloat codes (fp4/fp6/fp8 pairs) on a device whose conversion instruction reads its operands as bytes of one register converts NATIVELY — each pair read out of the word's ONE register by the conversion's own byte select, the results landing through one move the assembler folds away — never by the compiler's byte-isolation spelling. Source: tracel-ai/cubecl @ 07cd07a (#1975 squash; the #1976 constituent, subject verbatim [commit-message] 'perf(cuda): a word of e2m1 codes converts a byte at a time out of its one register'; Apache-2.0 OR MIT). THE ANTI-SHAPE, verbatim [in-diff, convert.rs ByteSelected doc]: 'Converted a pair at a time, the compiler first isolates each byte into a register of its own, five or six instructions a word.' (⚠ STAGED-TEXT CORRECTION carried: PRMT/LOP3/SHF byte-isolation is the OLD compiler behavior the fix REPLACES, not the fix; 'F2FP ... R.B1' is commit-message-only — the diff's PTX spells cvt.rn.f16x2). THE FIX, verbatim [in-diff] convert.rs:311-329 'fn byte_selected': '.reg .b8 b0, b1, b2, b3;' / '.reg .b32 h0, h1, h2, h3;' / 'mov.b32 {b0, b1, b2, b3}, $1;' / 'cvt.rn.f16x2.{pair} h0, b0;' (x4) / 'mov.b128 pairs, {h0, h1, h2, h3};' / 'mov.b128 $0, pairs;' with the load-bearing comment [in-diff] :316-317 '`$0` reads as the four result registers together, so the pairs reach it through one 128-bit move, which the assembler folds away.' ADMISSION is capability-gated four-conjunct, verbatim [in-diff] :299-306 'fn byte_pairs_in_a_word': 'value.is_packed_fp6_fp8_fp4(ctx) && value.scalar_ty(ctx).size(ctx) == 1 && value.vector_size(ctx) == WORD_BYTES && ... options.supports_features.byte_pair_conversion' (const WORD_BYTES = 4; the flag [in-diff] shared/base.rs:110 'pub byte_pair_conversion: bool,', armed [in-diff] cubecl-cuda/src/runtime.rs:383 for arch_major 10/11/12). The enum doc states the law, verbatim [in-diff] :274-277: 'A word of byte-wide pairs on a device that converts them itself: each pair read out of the word's one register by the conversion's own byte select ([byte_selected]).' Dispatch rides a MinifloatSource-once refactor (NotConverted | Converted | ByteSelected — both should_lower and lower branch on the ONE classification, never re-test is_fp8_fp6_fp4 per site). Distinct from lut-free-bit-spread-vadd4-unpack (gpu_33 — decode ARITHMETIC replacing a LUT inside a GEMM's hot loop; THIS is the CAST path's lowering granularity), from minifloat-normal-code-shift-bias-diff-decode (gpu_77 — the decode's shift/bias arithmetic identity; THIS is which instructions MOVE the codes into the converter), from fp4-nibble-gather-lut-replicated-index-width (gpu_61 — the gather-LUT index-width axis of FP4->FP8 decode; THIS is the hardware cvt's byte-select axis), from dequant-byte-pairs-as-aligned-u16-loads (gpu_13, L — the LOAD granularity of dequant byte pairs; THIS is the cast instruction's operand granularity), and from the exact-widening family (storage-form widening; THIS widens nothing stored — the word is converted as stored). NotBenchable here (CUDA PTX lowering on arch_major >= 10; the admission gate, the one-register read model, and the fold-away result move are CPU-testable and ARE the fixtures). Batch 320 / Plan 320.".to_string(),
            ref_shape: "// naive: the compiler isolates each byte into a register of its own\n// (PRMT/LOP3/SHF), then converts — five or six instructions a word\nfn convert_word_isolated(word: u32) -> [f16; 8] {\n    let b0 = isolate(word, 0); // PRMT/LOP3/SHF: a private register per byte\n    let b1 = isolate(word, 1);\n    let b2 = isolate(word, 2);\n    let b3 = isolate(word, 3); // 'five or six instructions a word' BEFORE\n    [cvt(b0), cvt(b1), cvt(b2), cvt(b3)] // any conversion runs\n}".to_string(),
            opt_pattern: "// optimized: the word splits ONCE; each pair is read out of THAT one\n// register by the conversion's own byte select; the results land as one\n// move the assembler folds away\n//   .reg .b8 b0, b1, b2, b3;\n//   mov.b32 {b0, b1, b2, b3}, $1;          // the ONLY extraction\n//   cvt.rn.f16x2.{pair} h0, b0;            // x4 — the byte select is the\n//   cvt.rn.f16x2.{pair} h1, b1;            //   conversion's own operand\n//   cvt.rn.f16x2.{pair} h2, b2;\n//   cvt.rn.f16x2.{pair} h3, b3;\n//   mov.b128 $0, {h0, h1, h2, h3};         // folded away by the assembler\nfn convert_word_native(word: u32) -> [f16; 8] {\n    byte_selected(word) // admitted: packed minifloat && byte-wide && a whole\n}                       // word && the backend's byte_pair_conversion flag".to_string(),
        },
        // ── B: a block-scaled instruction reads the form the blueprint states —
        // the operand contract is declared data, every mismatch refuses per axis. ──
        KernelRule {
            rule_id: "block-scaled-operand-declared-form-refusal-ladder".to_string(),
            gpu_concept: "MECHANISM (the operand contract as declared data; category B — Compute, the MMA instruction family): a block-scaled MMA instruction's operands are governed by a DECLARED form — each input's code element AS THE INSTRUCTION'S REGISTERS HOLD IT (e2m1x2 for e2m1 codes two to a byte, e4m3 for one to a byte), the scales' element, and the values of k one scale covers — and the kernel REFUSES, per axis and loud, any operand whose stored codes, words or scales are not the form's, instead of assuming defaults. Source: tracel-ai/cubecl @ 07cd07a (#1975 squash; the #1977 constituent 'Tile: the block-scaled instruction reads the form the blueprint states', Apache-2.0 OR MIT). THE DELETED ASSUMPTION, verbatim [commit-message]: 'refuses an operand whose stored codes, words or scales are not the form's, instead of assuming e2m1 under e4m3 scales of sixteen.' THE FORM as data, verbatim [in-diff] instruction.rs:233-236: 'The form of a block-scaled instruction's operands: what each input's registers hold, what its scales are, and how many values of k one scale covers. Any form the device's instruction takes ([ScaledMmaConfig]); the inputs may hold different codes, under scales of one type and one block.' — struct BlockScaledOperands { lhs, rhs, scales: FloatKind, block: usize } with doc [in-diff] :239-240 'The `A`'s codes as a register of the instruction holds them: `e2m1x2` for `e2m1` codes two to a byte, `e4m3` for one to a byte.' SCALE WORDS NAME THEIR FIELD, verbatim [in-diff] packing/base.rs:28 doc: 'Stored `u32` words of `field`-wide values, served as stored like [Plain]: a reader takes a word whole, its fields in place, as a block-scaled instruction takes a register of its scales. The field says what the word holds, which a word read whole would otherwise not.' (Packing::Words { field } — a reader takes the scale type FROM THE WORDS, never reads any plain u32 scale tile as four e4m3). THE REFUSAL LADDER, verbatim strings [in-diff] block_scaled.rs: 'a register of the instruction holds its {held:?} codes one a byte, which no packed word stores' / 'the operand is stored as {packing:?}, not packed {held:?} codes' / 'the operand stores {packing:?} words, and a register of the instruction holds {registers} codes' / 'a depth of {k} is not whole blocks of {form.block}' / 'the scales are words of {word_field:?}, and the instruction reads {..}' / 'a word holds {} scales, and one step of the instruction reads {step_scales}' — every refusal names its axis, and the hard-coded constant is GONE: E2M1_SCALE_BLOCK -> form.block in the refusal + SCALE_READ = 16 with doc [in-diff] 'Values of `k` a run reads one scale for: sixteen, the narrowest block a format scales, so a run under any block of a multiple of it reads each value's scale.' The stepped decode keeps its own guard, verbatim [commit-message]: 'The stepped e2m1 decode reads only e4m3 words, and refuses others.' Distinct from mma-accumulator-run-as-one-operand-depth-matches-instruction (gpu_141, B — the RUN-DEPTH axis of the same 'the instruction defines the contract' family; THIS is the OPERAND-FORM axis — compose, never merge), from dpas-block-scale-after-accumulate-not-in-operand (gpu_102 — WHERE the scale is applied, Intel DPAS; THIS is what the operand must BE), from superblock-scale-replication-to-subblock-scale-slots (gpu_89 — scale-slot LAYOUT; THIS is the form DECLARATION and its refusals), from one-pack-serves-all-schedules-nibble-order-contract (gpu_125, L — the pack's slot-ORDER contract across schedules; THIS is the instruction-form contract at the MMA site), from vector-width-admission-checks-every-outer-stride (gpu_136, N — the stride-multiple admission axis), and from the exact-widening family (dtype widening licenses; THIS widens nothing — it refuses what does not match the declared form). NotBenchable here (Blackwell-class block-scaled MMA; the refusal ladder, the field-naming contract, and the k-coverage arithmetic are CPU-testable and ARE the fixtures). Batch 320 / Plan 320.".to_string(),
            ref_shape: "// naive: the form is ASSUMED — every operand reads as e2m1 codes\n// under e4m3 scales of sixteen, whatever actually arrived\nfn load_block_scaled_default(operand: &Operand) -> Fragments {\n    // no declaration: an e4m3-code operand silently decodes as e2m1 pairs,\n    // a 64-wide scale block silently reads as 16, a plain-u32 scale word\n    // silently reads as four e4m3 — wrong products with no refusal\n    decode_as_e2m1_scales_e4m3_16(operand)\n}".to_string(),
            opt_pattern: "// optimized: the form is DECLARED data; every axis refuses loud\nstruct BlockScaledOperands { lhs: FloatKind, rhs: FloatKind,\n                             scales: FloatKind, block: usize }\nfn refuse_unless_block_scaled(op: &Operand, form: &BlockScaledOperands)\n                              -> Result<Fragments, String> {\n    if op.codes_per_byte() != codes_per_byte(form.lhs) {\n        return Err(\"a register of the instruction holds its {held:?} codes\n                    one a byte, which no packed word stores\".into());\n    } // ... one refusal per axis: packing vs held codes, registers-per-word,\n      // k % form.block (the form's block, never a hard-coded constant),\n      // scale-word field vs the instruction's read, per-word scale count\n    Ok(build_instruction_from(form).load(op))\n}\n// scale words carry their field: Packing::Words { field } served as stored —\n// a plain u32 scale word is never read as four e4m3 by assumption".to_string(),
        },
        // ── D: a plane's units exchanging through GLOBAL memory need a barrier
        // whose scope covers storage — the shared-only plane barrier does not. ──
        KernelRule {
            rule_id: "plane-storage-barrier-scope-covers-global-exchange".to_string(),
            gpu_concept: "MECHANISM (barrier memory-class selection by sharing topology; category D — Dispatch, the backend op/semantics axis): units of a PLANE (subgroup/warp) that write GLOBAL memory and read each other's writes need a barrier whose MEMORY SCOPE covers storage memory — the shared-memory-only plane barrier does not promise it, and the cube-wide storage barrier covers it but is sufficient-and-stronger (every unit of the cube must reach it). Source: tracel-ai/cubecl @ 07cd07a (#1975 squash; the #1986 constituent 'sync_plane_storage: a plane barrier that also orders storage memory', Apache-2.0 OR MIT). THE HAZARD, verbatim [commit-message]: 'sync_plane orders shared memory only: Metal's simdgroup barrier takes mem_threadgroup, SPIR-V's subgroup barrier workgroup memory, WGSL a workgroup barrier. A plane whose units write global memory and read each other's writes had no barrier that promised it; sync_storage does, but every [unit of the cube must reach it].' THE FIX: a new SyncPlaneStorageOp — [in-diff] ir/dialect/synchronization.rs:57 'pub struct SyncPlaneStorageOp {}' beside SyncOp — lowered per backend with the scope carrying BOTH classes: Metal [in-diff] metal/dialect.rs:217-218 'simdgroup_barrier(mem_flags::mem_device | mem_flags::mem_threadgroup);' with the comment :216 'The simdgroup barrier's device flag is what orders the plane's storage writes for its own units.'; SPIR-V [in-diff] spirv/src/ops/sync.rs a subgroup barrier with ACQUIRE_RELEASE | UNIFORM_MEMORY | WORKGROUP_MEMORY | MAKE_AVAILABLE and the comment verbatim 'A subgroup barrier over the storage class as well as the workgroup's. As at device scope, the availability and visibility operations are what carry one unit's plain writes to the others under the Vulkan memory model, here at the subgroup's scope.'; WGSL 'storageBarrier();\\nworkgroupBarrier();' (no plane barrier exists — the classes doubled); CUDA '__syncwarp();'; HIP/LLVM the plane barrier. THE LAW: pick the barrier whose scope's memory-class set CONTAINS every class the exchange crosses, at the NARROWEST extent that still covers the exchanging units (plane < cube — the exchange pays the plane's arrival, not the cube's). In-tree consumer, verbatim [in-diff] stage/transport/quantize.rs: 'The block scales calibrate_from writes may sit in global memory, which sync_plane did not order for the plane's own units.' ⚠ SINGLE-SOURCE DISCLOSED: one in-tree consumer today (the plane-held quantize transport) — landed as a correctness-axis law on the table-reached-buffers-declare-residency precedent (single-source, correctness class); the second-instance trigger rides the watch. Distinct from bounded-cross-worker-barrier-protocol-polling-fan-in-ladder (gpu_85 — a SOFTWARE device-scope spin protocol across THREADGROUPS; its mem_device fences are stage fences of that protocol, not a hardware barrier's memory-class selection), from epilogue-must-be-workgroup-local (gpu_03 — cross-workgroup read OWNERSHIP legality; THIS is the barrier SCOPE that orders an in-plane global exchange), from two-pass-partial-reduction-inter-dispatch-barrier (gpu_116 — encoder-level barriers BETWEEN dispatches; THIS is one dispatch's in-plane exchange), from barriers-declared-before-slots-one-free-run (gpu_142, E — declaration ORDER as allocation-fragmentation control; THIS is memory-class scope), from the smem free-legality faces (gpu_94's interleave/B259 predicate — whether a FREE may release; THIS is whether the EXCHANGE is ordered at all), and from workgroup-barrier participation universality (gpu_127 — every unit participates; THIS adds WHICH memory classes the participation orders). NotBenchable here (backend memory-model semantics; the scope-contains-exchange-classes check and the extent-narrowing law are CPU-testable and ARE the fixtures; the CUDA __syncwarp arm is the source's own spelling — its sufficiency rests on the source's runtime tests, not re-adjudicated here). Batch 320 / Plan 320.".to_string(),
            ref_shape: "// naive: a plane barrier picked by UNIT COUNT, not by the exchange's\n// memory classes — plane units write GLOBAL memory, read each other's\n// writes, and sync with the shared-memory-only plane barrier\nfn plane_exchange_ordered_by_sync_plane(writes: &mut [f32]) {\n    plane_store_global(writes);        // lands in storage memory\n    sync_plane();                       // orders THREADGROUP memory ONLY —\n    let peer = plane_load_global(idx);  // the read has NO promise: the\n    // write may not be visible to the peer unit at all\n}".to_string(),
            opt_pattern: "// optimized: the barrier's memory-class set covers the exchange; the\n// extent stays the plane (never the cube — every unit would have to reach)\nfn plane_exchange_ordered(writes: &mut [f32]) {\n    plane_store_global(writes);\n    sync_plane_storage(); // plane extent + {threadgroup, storage} classes:\n    //   Metal:   simdgroup_barrier(mem_device | mem_threadgroup)\n    //   SPIR-V:  subgroup barrier, ACQUIRE_RELEASE|UNIFORM|WORKGROUP|MAKE_AVAIL\n    //   WGSL:    storageBarrier(); workgroupBarrier();   (doubled — no plane bar)\n    //   CUDA:    __syncwarp()\n    let peer = plane_load_global(idx); // ordered: the write is visible\n}\n// the selection law: needed_classes(exchange) ⊆ barrier.scope.classes\n// && barrier.extent ⊇ exchanging_units, narrowed to the plane".to_string(),
        },
    ]
}

